INSERT INTO order_items(id,order_id,product_id,quantity,unit_price,discount)
SELECT id*2-1,id,((id-1)%8)+1,(id%3)+1,CASE ((id-1)%8)+1 WHEN 1 THEN 240 WHEN 2 THEN 45 WHEN 3 THEN 120 WHEN 4 THEN 65 WHEN 5 THEN 35 WHEN 6 THEN 25 WHEN 7 THEN 18 ELSE 32 END,CASE WHEN id%5=0 THEN 0.1 ELSE 0 END FROM orders;
INSERT INTO order_items(id,order_id,product_id,quantity,unit_price,discount)
SELECT id*2,id,((id+2)%8)+1,1,CASE ((id+2)%8)+1 WHEN 1 THEN 240 WHEN 2 THEN 45 WHEN 3 THEN 120 WHEN 4 THEN 65 WHEN 5 THEN 35 WHEN 6 THEN 25 WHEN 7 THEN 18 ELSE 32 END,0 FROM orders WHERE id%4<>0;
